Translate("deDE", "thousand-needles", {
	title = "Tausend Nadeln",
	aliases = { "die Nadeln" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tausend Nadeln ist eine große Schlucht aus rotem Stein südlich des {link:the-barrens}Brachlands{/link}. Ihr Boden ist trocken und staubig, und aus ihm erheben sich Hunderte schmaler Felsnadeln, so hoch und dünn, dass Reisende das ganze Land nach ihnen benannten. Die {link:tauren}Tauren{/link} erreichen es über den großen Aufzug an seinem Nordrand, und von den Tafelbergen des Freiwindpostens aus halten sie Wache über die Schlucht. Im Osten weicht der Stein der schimmernden Ebene, einer blendenden Salzfläche, auf der Goblins und {link:gnomes}Gnome{/link} Maschinen eigener Bauart um die Wette fahren lassen. Windschlangen winden sich zwischen den Nadeln, Wyvern nisten auf den westlichen Höhen, und {link:harpies}Harpyien{/link} kreischen in den südlichen Schluchten. Es ist ein schönes Land, und ein gefährliches.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet, wie die Nadeln dazu kamen, so zu stehen, wie sie stehen, noch wann die {link:the-shimmering-flats}schimmernde Ebene{/link} zu einer Salzwüste wurde. Die {link:tauren}Tauren{/link} durchwandern diese Schluchten seit Generationen, und die {link:centaurs}Zentauren{/link} jagten sie hier, wie sie sie über alle Ebenen {link:kalimdor}Kalimdor{/link}s jagten. Gelehrte, die zur Ebene kommen, bemerken, dass die Grenze zwischen den grünen Wäldern von {link:feralas}Feralas{/link} und dem trockenen Stein der Nadeln seltsam scharf ist, als hätte eine alte Magie sie gezogen. Keiner von ihnen kann sagen, welche Magie das war.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Die {link:tauren}Tauren{/link} des Freiwindpostens halten das Herz der Schlucht, doch viel mehr halten sie nicht. Die Galak-{link:centaurs}Zentauren{/link} überfallen ihre Karawanen von der {link:splithoof-crag}Spalthufklippe{/link} und vom {link:camp-e-thok}Camp E'thok{/link} aus, und sie haben geschworen, jeden Tauren zu töten, der es wagt, im Westen zu jagen. Auf dem {link:darkcloud-pinnacle}Düsterwolkengipfel{/link} bewachen Krieger des {link:grimtotem-clan}Klans der Grimmtotem{/link} die Begräbnisstätte ihrer Toten und empfangen Fremde, die im Geheimen kommen und gehen. Der {link:freewind-post}Freiwindposten{/link} beobachtet sie genau und traut ihnen mit jeder Jahreszeit weniger.

Im Osten ist die {link:the-shimmering-flats}schimmernde Ebene{/link} zum Schauplatz eines langen Wettstreits geworden. Auf der {link:mirage-raceway}Illusionenrennbahn{/link} jagen ein Goblinteam und ein Gnomenteam ihre Raketenwagen über das Salz, und die Hälfte der Schurken und Träumer der Welt kommt, um zuzusehen und zu wetten. Südlich der Rennstrecke gruben {link:dwarves}Zwerge{/link} der {link:explorers-league}Forscherliga{/link} an der {link:the-rustmaul-dig-site}Rustmaul-Grabungsstätte{/link} in die Erde, und etwas grub zurück: ein Schwarm großer Insekten, den die {link:horde}Horde{/link} nun {link:qiraji}Silithiden{/link} nennt. Am Nordrand, nahe dem Aufzug, halten die {link:quilboar}Stacheleber{/link} den Dornenbau der {link:razorfen-downs}Hügel von Razorfen{/link}, und auf den Pfaden in der Nähe wurden Kultisten in Roben gesehen.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die {link:tauren}Tauren{/link}.{/b} Krieger, Jäger und Schamanen halten den {link:freewind-post}Freiwindposten{/link} und das kleine Jagdlager des Weißgipfelpostens.
• {b}Die Grimmtotem.{/b} Ein Taurenklan für sich, der den {link:darkcloud-pinnacle}Düsterwolkengipfel{/link} hält und jedem anderen Stamm misstraut.
• {b}Die Galak-{link:centaurs}Zentauren{/link}.{/b} Plünderer, die die {link:splithoof-crag}Spalthufklippe{/link} und das {link:camp-e-thok}Camp E'thok{/link} halten und Krieg gegen die Tauren führen.
• {b}Die Goblins und {link:gnomes}Gnome{/link} der {link:mirage-raceway}Illusionenrennbahn{/link}.{/b} Mechaniker, Piloten, Buchmacher und Mitläufer.
• {b}Die {link:harpies}Harpyien{/link}.{/b} Die kreischenden Harpyien nisten im kreischenden Canyon und im {link:roguefeather-den}Bau der Wildfedern{/link}.
• {b}Die {link:qiraji}Silithiden{/link}.{/b} Insekten, die unter der {link:the-rustmaul-dig-site}Rustmaul-Grabungsstätte{/link} aus der Erde schwärmen.
• {b}Die Tiere.{/b} Windschlangen, Wyvern, Pumas, Hyänen, Basilisken, Skorpide und die großen Schildkröten des Salzes.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die Jahre der Wanderschaft.{/b} Die Taurenstämme durchquerten diese Schluchten auf ihren langen Wanderungen, gejagt von den {link:centaurs}Zentauren{/link}. Viele {link:tauren}Tauren{/link} des Freiwindpostens erinnern sich noch an jene Tage.
• {b}Die Inbesitznahme Mulgores.{/b} Als {link:cairne-bloodhoof}Cairne Bloodhoof{/link} sein Volk mit der Hilfe der {link:horde}Horde{/link} nach {link:mulgore}Mulgore{/link} führte, wurden die Tauren stark genug, um in die Nadeln zurückzukehren. Keine Chronik verzeichnet, wann sie den {link:freewind-post}Freiwindposten{/link} oder den großen Aufzug errichteten.
• {b}Die Ankunft der Rennfahrer.{/b} Goblins und {link:gnomes}Gnome{/link} fanden in der schimmernden Ebene den flachsten Boden Kalimdors, und sie bauten darauf eine Rennstrecke.
• {b}Die Gegenwart.{/b} Die Galak werden dreister, {link:grimtotem-clan}die Grimmtotem{/link} hüten Geheimnisse, und die {link:qiraji}Silithiden{/link} sind aus der Erde heraufgekommen.]=],
		},
		{
			title = "Überlieferungen der Nadeln",
			text = [=[• Die {link:tauren}Tauren{/link} des Weißgipfelpostens kennen eine Legende von {link:arikara}Arikara{/link}, einer Schlange der Rache, die aus dem heiligen Feuer des Düsterwolkengipfels gegen jene aufsteigt, die abscheuliche Taten begangen haben. Die meisten hielten sie nur für eine Legende.
• Die Galak bewachen ein Relikt aus den Tagen, als die ersten {link:centaurs}Zentauren{/link} geboren wurden, verwahrt in einer Höhle hinter einer Flamme, die niemals erlischt.
• Eine Hyäne, die die Tauren {link:steelsnap}Steelsnap{/link} nennen, schart andere Hyänen um sich und verbreitet Furcht unter den sanfteren Tieren der Schlucht.
• Die Boxencrews der {link:mirage-raceway}Illusionenrennbahn{/link} sagen, dass jeder Abschnitt der Ebene mit den Trümmern von Raketenwagen übersät ist und dass ein sorgfältiger Sammler davon leben kann.]=],
		},
	},
})

Translate("deDE", "freewind-post", {
	title = "Freiwindposten",
	aliases = { "Freiwind" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Freiwindposten ist die Taurenfestung von {link:thousand-needles}Tausend Nadeln{/link}, errichtet auf einer Gruppe von Tafelbergen in der Mitte der Schlucht. Brücken aus Seil und Holz verbinden die Gipfel der Tafelberge, und ein Aufzug trägt Reisende vom Boden der Schlucht hinauf. {link:cliffwatcher-longhorn}Klippenwächter Longhorn{/link} befehligt seine Krieger. Gastwirtin Abeqwa führt die Hütte, Montarr bewahrt die Überlieferungen der Stämme, und Nyses Windreiter tragen Nachrichten nach {link:thunder-bluff}Thunder Bluff{/link} und {link:the-crossroads}Crossroads{/link}. An einem Pfahl bei der Hütte hängt eine Bekanntmachung, die jeder Krieger gelesen hat: eine Belohnung für den verstoßenen Grimmtotem {link:arnak-grimtotem}Arnak{/link}. Von ihren Höhen aus können die {link:tauren}Tauren{/link} die Lager der Galak im Norden und den Gipfel der Grimmtotem im Nordwesten sehen.]=],
		},
	},
})

Translate("deDE", "the-great-lift", {
	title = "Der große Aufzug",
	aliases = { "großer Aufzug" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der große Aufzug verbindet den Südrand des {link:the-barrens}Brachlands{/link} mit dem Boden von {link:thousand-needles}Tausend Nadeln{/link}, tief darunter. Die {link:tauren}Tauren{/link} bauten ihn, und seine Plattformen steigen und sinken an langen Seilen neben der Klippe. Er ist der einzige leichte Weg von Norden in die Schlucht, und darum wird er bewacht. Grish Longrunner hält hier schon so lange Wache, dass er ihn einen Klotz Holz nennt, und er wartet seit vielen Jahreszeiten darauf, abgelöst zu werden, damit er seine Familie besuchen kann. Der Tapfere Moonhorn beobachtet den Pfad unten, wo die Überfälle der {link:centaurs}Zentauren{/link} in letzter Zeit häufiger geworden sind.]=],
		},
	},
})

Translate("deDE", "whitereach-post", {
	title = "Weißgipfelposten",
	aliases = { "Weißgipfel" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Weißgipfelposten ist ein kleines Lager der {link:tauren}Tauren{/link} im Nordwesten der Schlucht, südwestlich des großen Aufzugs und an der Straße nach {link:freewind-post}Freiwind{/link}. {link:kanati-greycloud}Kanati Greycloud{/link} errichtete es als Jagdlager, kühn genug, um in den westlichen Schluchten zu jagen, die die Galak beanspruchen. {link:motega-firemane}Motega Firemane{/link} ist mit dem jungen {link:pao-ka-swiftmountain}Pao'ka Swiftmountain{/link} hierher gekommen, um die Geschöpfe der Nadeln zu erforschen. Ein Goblintüftler, {link:wizlo-bearingshiner}Wizlo Bearingshiner{/link}, hat bei ihnen Zuflucht gesucht, nachdem die {link:centaurs}Zentauren{/link} seine Karawane vernichtet hatten. Die Galak wollen das Lager auslöschen, und seine wenigen Zelte werden stets bewacht.]=],
		},
	},
})

Translate("deDE", "darkcloud-pinnacle", {
	title = "Düsterwolkengipfel",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Düsterwolkengipfel ist eine Gruppe von Nadeln im Nordwesten der Schlucht, die der {link:grimtotem-clan}Klan der Grimmtotem{/link} hält. Pfade und Brücken klettern zwischen seinen Spitzen empor, und auf einer abgelegenen Nadel begraben die Grimmtotem ihre Toten neben einem heiligen Feuer des Lebens, das lange geruht hat. Der Klan bewacht den Ort erbittert. Agenten unbekannter Herkunft haben ihn heimlich besucht und versiegelte Briefe in den Truhen der Grimmtotem hinterlassen. {link:arnak-grimtotem}Arnak{/link} der Verstoßene lauert auf den Klippen in der Nähe, und hierher brachte er die Taurenfrau, die er geraubt hatte.]=],
		},
	},
})

Translate("deDE", "splithoof-crag", {
	title = "Spalthufklippe",
	aliases = { "Spalthufhöhle" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Spalthufklippe ist die Festung der Galak-{link:centaurs}Zentauren{/link}, ein Dorf aus Fellzelten an der Nordwand der Schlucht, östlich des Düsterwolkengipfels und nördlich des Freiwindpostens. Ihre Plünderer reiten gegen die Karawanen der {link:tauren}Tauren{/link} aus, und ihre Späher streifen bis an den Rand der Tafelberge von {link:freewind-post}Freiwind{/link}. Im hinteren Teil der Klippe liegt die Spalthufhöhle, eine bewachte Kaverne. Dort, hinter einer uralten Kohlenpfanne, deren Flamme niemals stirbt, bewahren die Galak den Cloven Hoof auf, ein Relikt aus der Zeit, als ihr Volk geboren wurde.]=],
		},
	},
})

Translate("deDE", "camp-e-thok", {
	title = "Camp E'thok",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Camp E'thok ist ein Kriegslager der Galak im äußersten Nordwesten von {link:thousand-needles}Tausend Nadeln{/link}, nicht weit unterhalb des Brachlands. In seiner Nähe liegen die zerbrochenen Wagen einer Goblinkarawane, über die die {link:centaurs}Zentauren{/link} herfielen und die sie plünderten. Sie nahmen alles außer einem eingesperrten Panther, einem so wilden Tier, dass selbst die Zentauren es fürchten. Um den Hals des Panthers hängt noch immer die kostbare Vorrichtung von {link:wizlo-bearingshiner}Wizlo Bearingshiner{/link}, dem einzigen Überlebenden der Karawane. Die Hyäne {link:steelsnap}Steelsnap{/link} und ihr Rudel streifen über die Hänge in der Nähe.]=],
		},
	},
})

Translate("deDE", "highperch", {
	title = "Der Steilhang",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Steilhang ist ein hoher Felssims am Westrand der Schlucht, erreichbar über eine Rampe an den Klippenwänden entlang. Er ist der Nistplatz der Wyvern des Steilhangs, und sie verteidigen ihre Eier mit wilder Hingabe. Die {link:tauren}Tauren{/link} von {link:freewind-post}Freiwind{/link} sammeln hier Eier, um neue Reittiere für die Windreiter der {link:horde}Horde{/link} aufzuziehen. Andere kommen wegen des Gifts der Wyvern, das in manchen Kreisen einen hohen Preis erzielt. Ein großer Wyvern, den die Jäger Heartrazor nennen, beherrscht den Himmel über den Nestern.]=],
		},
	},
})

Translate("deDE", "roguefeather-den", {
	title = "Bau der Wildfedern",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Bau der Wildfedern ist eine Höhle im Süden der Schlucht, westlich des Freiwindpostens, am Ende des kreischenden Canyons. Die kreischenden {link:harpies}Harpyien{/link} nisten dort, und in den Tiefen des Baus häufen sie die Nahrung auf, die sie aus der Schlucht gestohlen haben. Ihre Matriarchin, {link:grenka-bloodscreech}Grenka Bloodscreech{/link}, zeigt sich Fremden nicht, doch wer die Vorräte der Harpyien verdirbt, erfährt bald, wie schnell sie kommt. Aus diesem Grund schicken die {link:tauren}Tauren{/link}, die die Jungen prüfen, sie hierher, um ihre Ausdauer zu beweisen.]=],
		},
	},
})

Translate("deDE", "windbreak-canyon", {
	title = "Schlucht der heulenden Winde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Schlucht der heulenden Winde verläuft an der Nordseite der Straße zwischen dem {link:freewind-post}Freiwindposten{/link} und der schimmernden Ebene. Windschlangen nisten in ihren Höhlen am Fuß der Klippen, und in der Dämmerung winden sie sich über den Nadeln. In einer dieser Höhlen fand man die Schlangen, wie sie ein Ei bewachten, das nicht ihr eigenes war. Auf einer einsamen Anhöhe nahe der Schlucht lebt {link:dorn-plainstalker}Dorn Plainstalker{/link}, der die Jungen jedes Stammes prüft, und in seiner Nähe wohnt die Schamanin {link:prate-cloudseer}Prate Cloudseer{/link}, die für die Geister der Luft spricht.]=],
		},
	},
})

Translate("deDE", "the-shimmering-flats", {
	title = "Die schimmernde Ebene",
	aliases = { "schimmernde Ebene" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die schimmernde Ebene füllt den Südosten von {link:thousand-needles}Tausend Nadeln{/link}: eine Fläche aus weißem Salz, so flach und so hell, dass die Luft darüber in der Hitze zittert. Salzverkrustete Skorpide, Basilisken, Geier und große funkelnde Schildkröten leben darauf, und sie werden größer, als irgendwer erklären kann. Goblins und {link:gnomes}Gnome{/link} haben die Ebene zu ihrem Rennplatz gemacht, und das Donnern ihrer Motoren hallt von den Wänden der Schlucht wider. An ihrem Südrand gruben die {link:dwarves}Zwerge{/link} die {link:the-rustmaul-dig-site}Rustmaul-Grabungsstätte{/link}. An ihrer Nordgrenze hält ein zerschlagener Kriegstrupp der {link:horde}Horde{/link} Wache.]=],
		},
	},
})

Translate("deDE", "mirage-raceway", {
	title = "Illusionenrennbahn",
	aliases = { "die Rennbahn" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Illusionenrennbahn ist eine Strecke, die auf der schimmernden Ebene angelegt ist, mit den Boxen zweier rivalisierender Teams an beiden Enden einer Tribüne. Die Goblins bauen ihre Rennwagen mit zwei Motoren und mehr Feuer als Verstand. Die {link:gnomes}Gnome{/link}, angeführt von den Brüdern Brassbolts, bauen mit Sorgfalt und verunglücken trotzdem. {link:race-master-kronkrider}Rennleiter Kronkrider{/link} herrscht über die Strecke, Ansager rufen die Quoten aus, und Händler verkaufen der Menge Getränke und Eiscreme. Hinter dem Lärm steckt Geld, und wo Geld ist, gibt es Ränke: gestohlene Pläne, bestochene Crews und Piloten mit Geheimnissen, die sie verbergen müssen.]=],
		},
	},
})

Translate("deDE", "the-rustmaul-dig-site", {
	title = "Die Rustmaul-Grabungsstätte",
	aliases = { "Rustmaul-Grabungsstätte" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Rustmaul-Grabungsstätte liegt am Südrand der schimmernden Ebene, wo ein Grabungstrupp der {link:explorers-league}Forscherliga{/link} in die Erde schnitt. Die {link:horde}Horde{/link} schickte einen Kriegstrupp, um die {link:dwarves}Zwerge{/link} zu vertreiben. Der Überfall gelang, doch mitten darin brach ein Schwarm großer Insekten aus einer Höhle in der Grabung hervor, und mehr als die Hälfte der {link:orcs}Orcs{/link} kehrte nie heim. Die Zwerge sind nun fort. Die Insekten bleiben, und ihre Zahl wächst: Sucher, Drohnen und Eindringlinge mit Panzern, die stärker sind als jede Rüstung, die die Schmiede der Horde kennen.]=],
		},
	},
})

Translate("deDE", "cliffwatcher-longhorn", {
	title = "Klippenwächter Longhorn",
	subtitle = "Befehlshaber des Freiwindpostens",
	found = "Freiwindposten",
	hint = [=[Sprecht mit dem Klippenwächter, der die Krieger des Freiwindpostens befehligt.]=],
	allegiance = "Horde · Freiwindposten",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Klippenwächter Longhorn befehligt die Krieger des Freiwindpostens. Von den hohen Tafelbergen aus überblickt er ganz {link:thousand-needles}Tausend Nadeln{/link}, und nichts darin gefällt ihm. Die Galak überfallen seine Karawanen, {link:grimtotem-clan}die Grimmtotem{/link} halten auf dem {link:darkcloud-pinnacle}Düsterwolkengipfel{/link} ihren eigenen Rat, und ein Mörder dieses Klans streift frei über die Klippen. Er ist ein harter und zorniger Anführer, der ein Unrecht an seinem Volk nur langsam vergibt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Longhorn ist der Erste, der die Gestalt des Unheils erkennt, das sich in den Nadeln zusammenbraut. Die {link:centaurs}Zentauren{/link} sind nur sein lautester Teil. Seine Entdeckung, dass {link:grimtotem-clan}die Grimmtotem{/link} mit Fremden von jenseits Kalimdors verhandeln, ist eine Warnung, die weit über eine einzelne Schlucht hinausreicht.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schwor den Galak Rache, als sie eine seiner Versorgungskarawanen niedermetzelten.
• Er setzte das Kopfgeld auf {link:arnak-grimtotem}Arnak Grimtotem{/link} aus, wegen Mordes und Entführung.
• Er schickte Späher auf den {link:darkcloud-pinnacle}Düsterwolkengipfel{/link}, um zu erfahren, was {link:grimtotem-clan}die Grimmtotem{/link} verbargen.
• Er hält seinen Bruder Nataka, fern in {link:desolace}Desolace{/link}, über die Bewegungen der {link:centaurs}Zentauren{/link} auf dem Laufenden.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Über Longhorns Leben vor dem {link:freewind-post}Freiwindposten{/link} ist wenig geschrieben. Bekannt ist nur, dass er einen Bruder hat, Nataka, der am {link:ghost-walker-post}Geistwandlerposten{/link} in {link:desolace}Desolace{/link} dient, und dass zwischen zweien seiner Briefe an ihn ein Jahr verging.]=],
		},
	},
	chapters = {
		{
			title = "Der Zorn von Freiwind",
			hint = [=[Bringt die dringende Botschaft vom großen Aufzug zum Freiwindposten.]=],
			text = [=[Ein Krieger am großen Aufzug meldete, dass die {link:centaurs}Zentauren{/link} ihre Überfälle wieder aufgenommen hatten. Die Nachricht kam für eine von Longhorns Karawanen zu spät: Die Galak waren bereits über sie hergefallen und hatten jeden {link:tauren}Tauren{/link} getötet, der mit ihr ritt. Longhorn nannte es eine Schandtat und schwor, dass sie nicht ungestraft bleiben würde. Er schickte jeden willigen Krieger gegen das Lager der Galak nördlich des Postens.]=],
		},
		{
			title = "Die geheimen Briefe",
			hint = [=[Erfahrt, was die Grimmtotem auf dem Düsterwolkengipfel verbergen.]=],
			text = [=[Über mehrere Wochen hinweg hatte man drei Fremde unbekannter Herkunft gesehen, die {link:grimtotem-clan}die Grimmtotem{/link} besuchten. Longhorn erfuhr, dass jeder von ihnen eine Botschaft in einer eigenen Truhe auf dem {link:darkcloud-pinnacle}Düsterwolkengipfel{/link} hinterlassen hatte, und er ließ sie holen. Die Briefe waren an einen gewissen Agasham gerichtet und von dreien unterzeichnet, die sich Vorboten nannten. Sie sprachen von einem Bündnis, das die anderen Taurenstämme niemals entdecken dürften, von völligem Gehorsam und von Agenten aus {link:lordaeron}Lordaeron{/link}, die sich bald mit Agashams Abgesandten treffen würden. Longhorn las sie und nannte die Nachricht verhängnisvoll. Er begann, sich auf das vorzubereiten, was kommen mochte.]=],
		},
	},
	mentions = {
		{
			text = [=[Botschaft an den {link:freewind-post}Freiwindposten{/link}, überbracht vom Boten des Tapferen Moonhorn]=],
		},
		{ text = "Befriedet die {link:centaurs}Zentauren{/link}" },
		{ text = "Spionage bei den Grimmtotem" },
		{ text = "Gesucht: {link:arnak-grimtotem}Arnak Grimtotem{/link}" },
		{ text = "Stammbaum, ein Bericht für seinen Bruder" },
	},
	bonds = {
		{ id = "arnak-grimtotem", name = "Arnak Grimtotem", note = "der Verstoßene, den er vor Gericht gebracht sehen will" },
