Translate("deDE", "hagar-lightninghoof", {
	title = "Hagar Lightninghoof",
	subtitle = "Gelehrter des Freiwindpostens",
	found = "Freiwindposten",
	hint = [=[Sprecht mit dem Tauren des Freiwindpostens, der neugierig auf ein seltsames Ei ist.]=],
	allegiance = "Horde · Freiwindposten",
	aliases = { "Hagar" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hagar Lightninghoof ist ein Taure des Freiwindpostens mit einem Hunger nach dem Unbekannten. Als ihn Gerüchte von einem seltsamen Ei erreichten, das von den Windschlangen bewacht wurde, wollte er es mit eigenen Augen sehen. Er ließ es nach {link:freewind-post}Freiwind{/link} bringen, und er sah zu, wie es schlüpfte.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Was aus dem Ei kam, war eine junge Schlange der Rache, und Hagar begriff sofort, dass die alte Legende von {link:arikara}Arikara{/link} wahr war. Seine Warnung setzte die {link:tauren}Tauren{/link} der Nadeln auf die Spur der Schlange.]=],
		},
	},
	chapters = {
		{
			title = "Das fremdartige Ei",
			hint = "Bringt Hagar das seltsame Ei aus den Schlangenhöhlen.",
			text = [=[Das Ei lag in einer Schlangenhöhle am Fuß der Klippen, und die Schlangen bewachten es, als wäre es eines ihrer eigenen. Als man es ihm brachte, beugte sich Hagar dicht darüber, um es zu untersuchen. Vor seinen Augen brach es auf. Er wischte sich die Stirn und sagte, die Rache sei nach {link:thousand-needles}Tausend Nadeln{/link} gekommen, und er schickte sofort Nachricht an {link:motega-firemane}Motega Firemane{/link}.]=],
		},
	},
	mentions = {
		{ text = "Fremdartiges Ei" },
		{ text = "Wilde Schlange" },
	},
	bonds = {
		{ id = "motega-firemane", name = "Motega Firemane", note = "kannte die Legende" },
		{ id = "arikara", name = "Arikara", note = "schlüpfte vor seinen Augen" },
	},
})

Translate("deDE", "thalia-amberhide", {
	title = "Thalia Amberhide",
	subtitle = "Die in Freiwind wartete",
	found = "Freiwindposten",
	hint = [=[Sprecht mit der Taurin am Freiwindposten, die auf eine geraubte Freundin wartet.]=],
	allegiance = "Horde · Freiwindposten",
	aliases = { "Thalia" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Thalia Amberhide wartet am {link:freewind-post}Freiwindposten{/link} auf {link:lakota-windsong}Lakota Windsong{/link}, die der Verstoßene {link:arnak-grimtotem}Arnak{/link} auf den {link:darkcloud-pinnacle}Düsterwolkengipfel{/link} verschleppte. Sie gab die Hoffnung nie auf. Als Lakota zu ihr zurückkam, sagte Thalia, sie habe es die ganze Zeit in ihren Knochen gewusst.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Thalias Geduld ist das stille Ende einer der dunkelsten Geschichten der Nadeln. Sie bewahrt auf, was Lakotas ermordetem Bruder gehörte, und sie gibt es nur jenen, die {link:lakota-windsong}Lakota{/link} heimbrachten.]=],
		},
	},
	mentions = {
		{ text = "Endlich frei" },
	},
	bonds = {
		{ id = "lakota-windsong", name = "Lakota Windsong", note = "die, auf die sie wartete" },
		{ id = "arnak-grimtotem", name = "Arnak Grimtotem", note = "raubte Lakota" },
	},
})

Translate("deDE", "rau-cliffrunner", {
	title = "Rau Cliffrunner",
	subtitle = "Sucher des Cloven Hoof",
	found = "Freiwindposten",
	hint = [=[Sprecht mit dem Tauren des Freiwindpostens, der die Zentauren erforscht.]=],
	allegiance = "Horde · Freiwindposten",
	aliases = { "Rau" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Rau Cliffrunner ist ein Taure des Freiwindpostens, der die {link:centaurs}Zentauren{/link} verstehen will, nicht nur bekämpfen. Mit seinem Gefährten Zangen Stonehoof aus {link:thunder-bluff}Thunder Bluff{/link} machte er sich daran, den Cloven Hoof zu nehmen, ein Relikt, das die Galak seit der Zeit der Erschaffung ihres Volkes bewachen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Rau fand den Schlüssel zu den Verteidigungen der {link:centaurs}Zentauren{/link} in ihrer eigenen Abstammung. Weil Dryaden und Zentauren einen gemeinsamen Ursprung teilen, konnte das Wasser eines Mondbrunnens der {link:night-elves}Nachtelfen{/link} die ewige Flamme durchbrechen, die das Relikt bewachte.]=],
		},
	},
	chapters = {
		{
			title = "Die heilige Flamme",
			hint = [=[Bringt eine Phiole mit Mondbrunnenwasser zum Freiwindposten und setzt sie in der Spalthufhöhle ein.]=],
			text = [=[Das Wasser des Mondbrunnens konnte die Flamme in der {link:splithoof-crag}Spalthufhöhle{/link} nur für kurze Zeit löschen. Es war lang genug. Der Cloven Hoof wurde aus der Festung der {link:centaurs}Zentauren{/link} getragen, und Rau spürte eine seltsame Energie, die sich darin regte. Er glaubt, dass er den {link:tauren}Tauren{/link} überraschende Dinge über die Zentauren verraten wird, und er hat begonnen, ihn zu entschlüsseln.]=],
		},
	},
	mentions = {
		{ text = "Die heilige Flamme" },
		{ text = "Die heilige Flamme, der Cloven Hoof" },
	},
	bonds = {
		{ id = "zangen-stonehoof", name = "Zangen Stonehoof", note = "sein Gefährte in Thunder Bluff" },
	},
})

Translate("deDE", "motega-firemane", {
	title = "Motega Firemane",
	subtitle = "Hüter des Weißgipfelpostens",
	found = "Weißgipfelposten",
	hint = [=[Sprecht mit dem Tauren, der am Weißgipfelposten die Geschöpfe der Nadeln erforscht.]=],
	allegiance = "Horde · Weißgipfelposten",
	aliases = { "Motega" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Motega Firemane kam nach {link:thousand-needles}Tausend Nadeln{/link}, um die Geschöpfe zu erforschen, die dort leben, und er brachte den jungen {link:pao-ka-swiftmountain}Pao'ka Swiftmountain{/link} mit. Er schlägt seine Zelte am {link:whitereach-post}Weißgipfelposten{/link} im Nordwesten der Schlucht auf. Motega kennt die alten Geschichten der {link:tauren}Tauren{/link} besser als die meisten, und als eine Schlange der Legende in die Nadeln zurückkehrte, wandten sich die Tauren an ihn.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Motega ist die Brücke zwischen den Nadeln und der Alten Weisen. Er war es, der {link:magatha-grimtotem}Magatha Grimtotem{/link} Nachricht von der Schlange {link:arikara}Arikara{/link} schickte, und er empfing das Pulver, das sie aus dem heiligen Feuer rufen sollte. Er war auch der Erste, dem ihre Warnung seltsam vorkam.]=],
		},
		{
			title = "Taten",
			text = [=[• Er erforscht vom {link:whitereach-post}Weißgipfelposten{/link} aus die Geschöpfe von {link:thousand-needles}Tausend Nadeln{/link}.
• Er wacht über {link:pao-ka-swiftmountain}Pao'ka Swiftmountain{/link}, dessen Vater den Jungen nur ungern ziehen ließ.
• Er kennt die Legende von {link:arikara}Arikara{/link}, der Schlange, die geboren wurde, um abscheuliche Taten zu rächen.
• Er bat {link:magatha-grimtotem}Magatha{/link} um Hilfe, um das ruhende heilige Feuer des Düsterwolkengipfels zu entfachen.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Über Motegas Leben vor dem {link:whitereach-post}Weißgipfelposten{/link} ist wenig geschrieben. Wer Pao'kas Vater ist und warum er den Jungen Motega anvertraute, ist nicht verzeichnet.]=],
		},
	},
	chapters = {
		{
			title = "Der verlorene Junge",
			hint = "Bringt Pao'ka vom Steilhang nach Hause.",
			text = [=[{link:pao-ka-swiftmountain}Pao'ka{/link} ging allein auf den Steilhang, um die Wyvern zu erforschen, und kam nicht zurück. Als der Junge endlich heimgebracht wurde, war Motega außer sich. Er sagte, hätte er es gewusst, hätte er ihn an einen Totem gekettet. Unter dem Zorn war er dankbar, und er belohnte jene, die geholfen hatten.]=],
		},
		{
			title = "Die Legende von Arikara",
			hint = "Antwortet auf Hagar Lightninghoofs Warnung.",
			text = [=[Motega hatte sein ganzes Leben lang von {link:arikara}Arikara{/link} gehört und nie geglaubt, dass er sie sehen würde. Nun war die Legende wahr. Um die Schlange zu jagen, musste das heilige Feuer des Lebens auf dem {link:darkcloud-pinnacle}Düsterwolkengipfel{/link} entzündet werden, und nur ein mächtiger Schamane konnte die seltene Incendia-Agave verzaubern, die es entfachen würde. Motega schickte die gesammelte Agave zu {link:magatha-grimtotem}Magatha Grimtotem{/link} nach {link:thunder-bluff}Thunder Bluff{/link}.]=],
		},
		{
			title = "Eine beunruhigende Antwort",
			hint = "Erschlagt Arikara und kehrt zum Weißgipfelposten zurück.",
			text = [=[Die Alte Weise hatte gewarnt, dass {link:arikara}Arikara{/link} vielleicht {link:cairne-bloodhoof}Cairne Bloodhoof{/link} nachstelle, erzürnt, weil sich zu viel von den alten Überlieferungen der {link:tauren}Tauren{/link} verändert habe. Als die Schlange erschlagen war, schüttelte Motega den Kopf. Es ergab für ihn keinen Sinn, dass Arikara den Hochhäuptling jagen sollte. Doch er wollte nicht sagen, dass {link:magatha-grimtotem}Magatha{/link} sich irrte. Sie sei, sagte er, die Mächtigste unter ihnen.]=],
		},
	},
	mentions = {
		{ text = "Heimwärts" },
		{ text = "Wilde Schlange" },
		{ text = "Heiliges Feuer" },
		{ text = "{link:arikara}Arikara{/link}" },
	},
	bonds = {
		{ id = "pao-ka-swiftmountain", name = "Pao'ka Swiftmountain", note = "der Junge in seiner Obhut" },
		{ id = "hagar-lightninghoof", name = "Hagar Lightninghoof", note = "brachte ihm die Nachricht" },
		{ id = "magatha-grimtotem", name = "Magatha Grimtotem", note = "verzauberte das Pulver" },
		{ id = "arikara", name = "Arikara", note = "die Schlange der Legende" },
		{ id = "kanati-greycloud", name = "Kanati Greycloud", note = "teilt den Weißgipfelposten" },
	},
})

