Translate("deDE", "arnak-grimtotem", {
	title = "Arnak Grimtotem",
	subtitle = "Der Verstoßene",
	found = "Die Klippen nahe dem Düsterwolkengipfel",
	hint = [=[Stellt Euch dem Verstoßenen, der am Freiwindposten gesucht wird.]=],
	allegiance = "Klan der Grimmtotem (verstoßen)",
	aliases = { "Arnak" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Arnak ist ein Verstoßener des {link:grimtotem-clan}Klans der Grimmtotem{/link}, am {link:freewind-post}Freiwindposten{/link} wegen Mordes und Entführung gesucht. Er bat {link:lakota-windsong}Lakota Windsong{/link}, seine Gefährtin zu werden, und sie wies ihn ab. In derselben Nacht kam er zurück und nahm sie mit Gewalt. Ihr Bruder versuchte, ihn aufzuhalten, und Arnak tötete ihn. Dann trug er Lakota auf den {link:darkcloud-pinnacle}Düsterwolkengipfel{/link}.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Arnaks Verbrechen weckten den Zorn des ganzen Freiwindpostens. {link:cliffwatcher-longhorn}Klippenwächter Longhorn{/link} fürchtete, er werde nie vor Gericht gebracht werden, und sagte, die Nachricht von seinen Taten bringe sein Blut zum Kochen.]=],
		},
	},
	mentions = {
		{ text = "Gesucht: Arnak Grimtotem" },
		{ text = "Endlich frei" },
	},
	bonds = {
		{ id = "lakota-windsong", name = "Lakota Windsong", note = "die Frau, die er raubte" },
		{ id = "cliffwatcher-longhorn", name = "Klippenwächter Longhorn", note = "setzte das Kopfgeld auf ihn aus" },
	},
})

Translate("deDE", "lakota-windsong", {
	title = "Lakota Windsong",
	subtitle = "Gefangene des Düsterwolkengipfels",
