	aliases = { "Lakota" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Lakota Windsong wies den Verstoßenen {link:arnak-grimtotem}Arnak{/link} ab, als er sie bat, seine Gefährtin zu werden. Er kam in der Nacht zurück und raubte sie, und er tötete ihren Bruder, der kämpfte, um ihn aufzuhalten. Sie wurde zwischen den Nadeln des Düsterwolkengipfels festgehalten, trauerte um ihren Bruder und sehnte sich danach, zu {link:thalia-amberhide}Thalia Amberhide{/link} am {link:freewind-post}Freiwindposten{/link} zurückzukehren.]=],
