	chapters = {
		{
			title = "Endlich frei",
			hint = "Führt Lakota aus dem Düsterwolkengipfel hinaus.",
			text = [=[Der Weg aus dem Gipfel führte durch das Gebiet der Grimmtotem selbst. Lakota stieg lebend von den Nadeln herab und erreichte den {link:freewind-post}Freiwindposten{/link}, wo {link:thalia-amberhide}Thalia{/link} nie aufgehört hatte, auf sie zu warten. Dort sprach sie vom Mut derer, die sie heimgebracht hatten.]=],
		},
	},
	mentions = {
		{ text = "Endlich frei" },
	},
	bonds = {
		{ id = "thalia-amberhide", name = "Thalia Amberhide", note = "wartete auf sie" },
