	},
})

Translate("deDE", "arikara", {
	title = "Arikara",
	subtitle = "Schlange der Rache",
	found = "Das heilige Feuer des Düsterwolkengipfels",
	hint = [=[Entfacht das heilige Feuer dort, wo die Grimmtotem ihre Toten begraben.]=],
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Arikara ist eine Schlange aus der Legende der {link:tauren}Tauren{/link}, ein Geschöpf, das, wie es heißt, nur geboren wird, um Rache an jenen zu suchen, die abscheuliche Taten begangen haben. Das heilige Feuer des Lebens auf dem {link:darkcloud-pinnacle}Düsterwolkengipfel{/link}, lange Jahre ruhend, kann sie hervorrufen. In diesen Tagen wurde ihr Ei in einer Schlangenhöhle der Nadeln gefunden, und es schlüpfte am {link:freewind-post}Freiwindposten{/link}.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Arikara ist eine Legende, die wandelte. {link:magatha-grimtotem}Magatha Grimtotem{/link} warnte, dass die Schlange vielleicht Hochhäuptling {link:cairne-bloodhoof}Cairne Bloodhoof{/link} nachstelle, erzürnt über Veränderungen in den alten Überlieferungen der {link:tauren}Tauren{/link}. Manche am {link:whitereach-post}Weißgipfelposten{/link} fanden die Warnung schwer zu verstehen.]=],
		},
	},
	mentions = {
		{ text = "Fremdartiges Ei" },
		{ text = "Wilde Schlange" },
		{ text = "Heiliges Feuer" },
		{ text = "Arikara" },
	},
	bonds = {
		{ id = "magatha-grimtotem", name = "Magatha Grimtotem", note = "sprach von ihr" },
		{ id = "motega-firemane", name = "Motega Firemane", note = "kannte ihre Legende" },
		{ id = "hagar-lightninghoof", name = "Hagar Lightninghoof", note = "sah ihr Junges" },
	},
})

Translate("deDE", "dorn-plainstalker", {
	title = "Dorn Plainstalker",
	subtitle = "Prüfer der Jungen",
	found = "Eine einsame Anhöhe nordöstlich des Freiwindpostens",
	hint = [=[Sucht den Tauren auf, der die Jungen auf einer einsamen Anhöhe über den Nadeln prüft.]=],
	allegiance = "Horde",
	aliases = { "Dorn" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Dorn Plainstalker wohnt allein auf einer Anhöhe über den Nadeln, fern vom Treiben des Freiwindpostens. Er hält es für seine Pflicht, die Jungen jedes Stammes auf die Gefahren vorzubereiten, denen sie begegnen werden, wenn sie den Schutz der Heimat verlassen. Er prüft sie in drei Dingen: dem Geist, dem Körper und dem Verstand. Wer besteht, kehrt stärker zurück. Wer scheitert, sagt er, lernt, wie weit die Welt wahrhaftig ist.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Dorn ist ein Lehrer der alten Art. Es kümmert ihn nicht, aus welchem Stamm ein Krieger kommt, nur ob dieser Krieger bereit ist. Seine Prüfungen verbinden mehrere der Weisen der {link:horde}Horde{/link} in ganz {link:kalimdor}Kalimdor{/link} und darüber hinaus.]=],
		},
		{
			title = "Taten",
			text = [=[• Er prüft den Glauben, die Ausdauer, die Stärke und das Wissen der Jungen.
• Er schickt sie gegen die Matriarchin der {link:harpies}Harpyien{/link} im {link:roguefeather-den}Bau der Wildfedern{/link} und gegen das Elementar {link:rok-alim-the-pounder}Rok'Alim{/link}.
• Er schickt sie für die Prüfung des Wissens weiter zum Schamanen {link:braug-dimspirit}Braug Dimspirit{/link} im {link:stonetalon-mountains}Steinkrallengebirge{/link}.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Über Dorns Leben ist wenig geschrieben, und ebenso darüber, wie lange er seine Anhöhe schon hält. Sein Stamm wird nicht genannt.]=],
		},
	},
	chapters = {
		{
			title = "Der Sprung des Glaubens",
			hint = "Beweist Euren Glauben auf Dorns Anhöhe.",
			text = [=[Dorns erste Prüfung ist die seltsamste. Er verlangt von den Jungen, von den Planken seiner Anhöhe in die leere Luft zu treten, ohne jedes Versprechen, dass sie leben werden. Glaube, lehrt er, ist wichtiger, als viele ahnen. Es ist nicht immer wichtig, woran man glaubt, sondern dass man an etwas glaubt.]=],
		},
		{
			title = "Körper und Stärke",
			hint = "Besteht die Prüfungen der Ausdauer und der Stärke.",
			text = [=[Für den Körper schickt Dorn die Jungen in den {link:roguefeather-den}Bau der Wildfedern{/link}, um die Vorräte der {link:harpies}Harpyien{/link} zu verderben und {link:grenka-bloodscreech}Grenka Bloodscreech{/link} entgegenzutreten, wenn sie in ihrem Zorn kommt. Für die Stärke schickt er sie gegen {link:rok-alim-the-pounder}Rok'Alim{/link}, ein Elementar, das seit dem Zeitalter der Alten Götter in den Nadeln verweilt.]=],
		},
		{
			title = "Der letzte Übergang",
			hint = "Vollendet die Prüfung des Wissens und kehrt zu Dorn zurück.",
			text = [=[Die Prüfung des Wissens steht nicht ihm zu. Sie führt über {link:braug-dimspirit}Braug Dimspirit{/link} im {link:stonetalon-mountains}Steinkrallengebirge{/link} und weiter, zu Gelehrten fern der Nadeln. Wenn die Jungen endlich zu Dorn zurückkehren, sieht er sie an, als wären seit ihrem ersten Sprung viele Monde vergangen, und er sagt ihnen, dass ihr Verstand, ihr Körper und ihr Geist stark sind.]=],
		},
	},
	mentions = {
		{ text = "Prüfung des Glaubens" },
		{ text = "Prüfung der Ausdauer" },
		{ text = "Prüfung der Stärke" },
		{
			text = [=[Prüfung des Wissens, der Weg zu {link:braug-dimspirit}Braug Dimspirit{/link}]=],
		},
		{ text = "Der letzte Übergang" },
	},
	bonds = {
		{ id = "grenka-bloodscreech", name = "Grenka Bloodscreech", note = "die Prüfung der Ausdauer" },
		{ id = "rok-alim-the-pounder", name = "Rok'Alim the Pounder", note = "die Prüfung der Stärke" },
		{ id = "prate-cloudseer", name = "Prate Cloudseer", note = "wohnt nahe seiner Anhöhe" },
		{ id = "braug-dimspirit", name = "Braug Dimspirit", note = "nimmt die Prüfung des Wissens ab" },
	},
})

Translate("deDE", "prate-cloudseer", {
