	},
	mentions = {
		{ text = "Ruf der Luft" },
		{ text = "Ruf der Luft" },
	},
	bonds = {
		{ id = "dorn-plainstalker", name = "Dorn Plainstalker", note = "ihr Nachbar auf den Höhen" },
	},
})

