Translate("deDE", "rok-alim-the-pounder", {
	title = "Rok'Alim the Pounder",
	subtitle = "Ein Elementar des alten Zeitalters",
	found = "Westlich des Freiwindpostens",
	hint = [=[Stellt Euch dem uralten Elementar, das durch die westlichen Nadeln wandelt.]=],
	allegiance = "Keine",
	aliases = { "Rok'Alim" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Im Zeitalter der Alten Götter füllten Elementare einen großen Teil der Welt, an sie gebunden durch die Macht der Götter, denen sie dienten. Als die Alten Götter gestürzt wurden, schwanden die meisten Elementare aus der Welt und kehren nun nur noch auf den Ruf mächtiger Magier zurück. Einige wenige waren stark genug, um aus eigener Kraft zu bleiben. Rok'Alim ist eines von ihnen. Die {link:centaurs}Zentauren{/link} nennen ihn den Stampfer, wegen des Donners, den seine Fäuste machen, wenn sie niederfahren.]=],
		},
	},
	mentions = {
		{ text = "Prüfung der Stärke" },
	},
	bonds = {
		{ id = "dorn-plainstalker", name = "Dorn Plainstalker", note = "bestimmte ihn zur Prüfung" },
	},
})

