			text = [=[Steelsnap ist eine Hyäne der Nadeln, die andere Hyänen an sich zieht und sie anführt, um Furcht und Gemetzel unter den sanfteren Tieren zu verbreiten. Die Jäger der {link:tauren}Tauren{/link} jagen ihn nicht um der Nahrung willen und nicht um der Ehre willen. Sie jagen ihn, weil er ein Geschöpf außerhalb des Segens der {red:earth-mother}Erdenmutter{/red} ist, und das Land ohne ihn reiner ist.]=],
		},
	},
	mentions = {
		{ text = "Steelsnap" },
