})

Translate("deDE", "moktar-krin", {
	title = "Moktar Krin",
	subtitle = "Anführer eines zerschlagenen Kriegstrupps",
	found = "Die Nordgrenze der schimmernden Ebene",
	hint = [=[Findet den Orc, der ein Kriegslager an der Grenze der schimmernden Ebene hält.]=],
	allegiance = "Horde · Orgrimmar",
	aliases = { "Moktar" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Moktar Krin führte einen Kriegstrupp der {link:horde}Horde{/link} an, um die {link:dwarves}Zwerge{/link} der {link:explorers-league}Forscherliga{/link} aus der schimmernden Ebene zu vertreiben. Die Zwerge starben, doch während der Kämpfe brach ein Schwarm Insekten aus einer Höhle in der Grabung hervor und tötete mehr als die Hälfte seiner Krieger. Nun hält er sein Lager an der Grenze der Ebene mit einer Truppe, die zu verwundet ist, um zu marschieren. Er wartet auf Befehle von Belgrom Rockmaul in {link:orgrimmar}Orgrimmar{/link}, und er beobachtet den Süden.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Moktar war der Erste der {link:horde}Horde{/link}, der in den Nadeln auf die {link:qiraji}Silithiden{/link} traf, und er bezahlte dafür. Sein Bericht, zu Korran nach {link:the-crossroads}Crossroads{/link} gebracht, half der Horde, die Insekten allmählich zu verstehen.]=],
		},
	},
	chapters = {
		{
			title = "Der Schwarm wächst",
			hint = "Treibt die Insekten der Rustmaul-Grabungsstätte zurück.",
			text = [=[Belgrom wollte, dass die Insekten in die Tiefen zurückgedrängt würden, aus denen sie gekommen waren. Moktars Krieger konnten das nicht allein. Mit der Hilfe von Reisenden auf dem Weg zu den Rennen wurde der Schwarm ausgedünnt, und die Panzer der Toten wurden Korran zur Untersuchung geschickt.]=],
		},
	},
	mentions = {
		{ text = "Der Schwarm wächst" },
		{ text = "Der Schwarm wächst" },
		{ text = "Teile des Schwarms" },
	},
	bonds = {
		{ id = "korran", name = "Korran", note = "erforscht die Insekten in Crossroads" },
		{ id = "belgrom-rockmaul", name = "Belgrom Rockmaul", note = "sein Befehlshaber in Orgrimmar" },
	},
})

Translate("deDE", "pozzik", {
	title = "Pozzik",
	subtitle = "Chefmechaniker der Goblinrennfahrer",
	found = "Die Goblinboxen der Illusionenrennbahn",
	hint = [=[Sprecht mit dem Goblinmechaniker in den Goblinboxen der Illusionenrennbahn.]=],
	allegiance = "Steamwheedle-Kartell · Goblinrennteam",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Pozzik war einst einer der angesehensten Tüftler von Undermine. Er ließ die Tüftlergewerkschaft hinter sich, um an Rennwagen zu arbeiten, und das Erste, was er tat, war, die Zweimotorenmodelle zu entwerfen, die das Goblinteam noch immer fährt. Nun führt er dessen Mechaniker auf der schimmernden Ebene. Er wiegt jeden Bolzen und jeden Knochen, denn beim Rennen zählt jede Unze.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Pozzik ist das Gehirn des Goblinteams, und er verliert. Die {link:gnomes}Gnome{/link} holen auf, und er würde beinahe alles tun, um mitzuhalten: die Goblinbarone und Baumeister anrufen, die ihn unterstützen, und, wenn es sein muss, seine Rivalen bestehlen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er entwarf die Zweimotoren-Rennwagen der Goblins.
• Er baut seine Rahmen aus den hohlen Knochen der Geier der Ebene.
• Er suchte über {link:gazlowe}Gazlowe{/link} aus {link:ratchet}Ratchet{/link} und {link:baron-revilgaz}Baron Revilgaz{/link} aus {link:booty-bay}Booty Bay{/link} einen neuen Treibstoffregler.
• Er ließ die Pläne von Rizzle Brassbolts stehlen und erfuhr daraus das Geheimnis des Induriums.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Über Pozziks Jahre in Undermine ist wenig geschrieben, ebenso darüber, warum er es verließ.]=],
		},
	},
	chapters = {
		{
			title = "Goblinsponsoring",
			hint = [=[Findet heraus, was aus dem Treibstoffregler wurde, der Pozzik versprochen war.]=],
			text = [=[{link:gazlowe}Gazlowe{/link} hatte einen neuen Treibstoffregler versprochen, und er kam nie an. Die Spur führte von {link:ratchet}Ratchet{/link} zu den Kais von {link:booty-bay}Booty Bay{/link} und zu {link:baron-revilgaz}Baron Revilgaz{/link}, der zugab, dass seine Männer die Baupläne nicht gefunden hatten. Die Pläne lagen im Haus eines Vorarbeiters der {link:venture-company}Venture Co.{/link} im {link:stranglethorn-vale}Schlingendorntal{/link}, der den neuen Regler in seine Schredder eingebaut hatte. Als die Baupläne Pozzik endlich erreichten, waren es nur Zeichnungen. Er war trotzdem zufrieden, denn nun konnte er die Konstruktion von Grund auf verbessern.]=],
		},
		{
			title = "Mithalten",
			hint = [=[Helft Pozzik, das Geheimnis der Geschwindigkeit der Gnome zu ergründen.]=],
			text = [=[Die Gnomenwagen waren schneller geworden, doch jede Konstruktion, die Pozzik sehen konnte, war dieselbe wie zuvor. Er schloss daraus, dass die {link:gnomes}Gnome{/link} einen neuen Werkstoff gefunden hatten. Während Zamek für Ablenkung sorgte, wurden Rizzle Brassbolts' Pläne unter seiner Nase weggenommen. Sie sprachen von Indurium, einem Erz aus der Zwergengrabung von {link:uldaman}Uldaman{/link}, das großer Hitze widersteht, und ein Klumpen davon hatte als Briefbeschwerer gedient.]=],
		},
	},
	mentions = {
		{ text = "Ladung erleichtern" },
		{ text = "Goblinsponsoring" },
		{ text = "Goblinsponsoring, die heimgebrachten Baupläne" },
		{ text = "Der achtzehnte Pilot" },
		{ text = "Mithalten" },
		{ text = "Rizzles Schaltpläne" },
		{ text = "Induriumerz" },
	},
	bonds = {
		{ id = "razzeric", name = "Razzeric", note = "der Pilot des Teams" },
		{ id = "gazlowe", name = "Gazlowe", note = "ein Sponsor" },
		{ id = "fizzle-brassbolts", name = "Fizzle Brassbolts", note = "ein Rivale" },
		{ id = "race-master-kronkrider", name = "Rennleiter Kronkrider", note = "leitet die Rennstrecke" },
	},
})

Translate("deDE", "razzeric", {
	title = "Razzeric",
	subtitle = "Der achtzehnte Pilot",
	found = "Die Goblinboxen der Illusionenrennbahn",
	hint = [=[Sprecht mit dem Goblinpiloten, der mehr Leistung mag, als ihm guttut.]=],
	allegiance = "Goblinrennteam",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Razzeric ist der Pilot des Goblinrennteams, der achtzehnte, der diesen Sitz innehat. Einst erledigte er Botengänge in den Boxen. Nun fährt er, und nachdem {link:pozzik}Pozzik{/link} jeden Rennwagen fertiggestellt hat, lockert Razzeric die Steuerung, entkernt den Rahmen und fügt mehr Feuer hinzu. Pozzik stellte einen Eimer Sand unter seinen Sitz. Razzeric kann es ihm nicht verzeihen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Razzeric ist der Grund, warum die Goblins gewinnen, wenn sie gewinnen, und der Grund, warum sie brennen, wenn sie brennen. Sein eigener Ingenieur in {link:gadgetzan}Gadgetzan{/link} fragte sich laut, ob der neunzehnte Pilot etwas taugen würde.]=],
		},
	},
	chapters = {
		{
			title = "Sicherheit geht vor",
			hint = "Lasst die Sicherung von Razzerics Verstärker entfernen.",
			text = [=[Razzeric bestellte einen Seaforium-Verstärker bei {link:shreev}Shreev{/link} vom Gizmorium in {link:gadgetzan}Gadgetzan{/link}, in {link:tanaris}Tanaris{/link}. Der Zeppelin, der ihn trug, stürzte in den {link:dustwallow-marsh}Marschen von Dustwallow{/link} ab, und als der Verstärker endlich gefunden wurde, war die Sicherung noch eingebaut. Razzeric schickte ihn zurück. Shreev, der ihn bereits weit gefährlicher gemacht hatte, als klug war, nahm die Sicherung heraus.]=],
		},
	},
	mentions = {
		{ text = "Der achtzehnte Pilot" },
		{ text = "Razzerics Tüftelei" },
		{ text = "Sicherheit geht vor" },
		{ text = "Sicherheit geht vor, der zurückgegebene Verstärker" },
	},
	bonds = {
		{ id = "pozzik", name = "Pozzik", note = "sein Mechaniker" },
	},
})

Translate("deDE", "fizzle-brassbolts", {
	title = "Fizzle Brassbolts",
	subtitle = "Gnomischer Rennfahrer der schimmernden Ebene",
	found = "Die Gnomenboxen der Illusionenrennbahn",
	hint = [=[Sprecht mit dem aufgeregten Gnom, der den gnomischen Raketenwagen entwirft.]=],
	allegiance = "Gnomisches Rennteam",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Fizzle Brassbolts hat mehr Entwürfe für seinen Raketenwagen, als er je bauen kann, und er will sie alle ausprobieren. Er arbeitet an einem Treibstoff, der heißer brennt als jeder zuvor, und an einem Motor, von dem er schwört, dass er den Wagen fliegen lassen wird. Mit seinen Brüdern Wizzle und Rizzle führt er das Gnomenteam auf der {link:mirage-raceway}Illusionenrennbahn{/link}.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Fizzles Suche nach Kolben, die seinen Motor überstehen könnten, führte ihn zu {link:martek-the-exiled}Martek{/link} dem Verbannten im {link:badlands}Ödland{/link}, und von Martek zum Indurium. Diese Entdeckung machte die Gnomenwagen schneller als je zuvor, und die Goblins bemerkten es.]=],
		},
	},
	mentions = {
		{ text = "Salzebenen-Gift" },
		{ text = "{link:martek-the-exiled}Martek der Verbannte{/link}" },
		{ text = "Neuigkeiten für Fizzle" },
		{ text = "Lieferung an die {link:gnomes}Gnome{/link}" },
	},
	bonds = {
		{ id = "wizzle-brassbolts", name = "Wizzle Brassbolts", note = "sein Bruder" },
		{ id = "pozzik", name = "Pozzik", note = "sein Rivale" },
		{ id = "kravel-koalbeard", name = "Kravel Koalbeard", note = "führte seine Teilebestellung aus" },
	},
})

Translate("deDE", "wizzle-brassbolts", {
	title = "Wizzle Brassbolts",
	subtitle = "Der vorsichtige Brassbolts",
	found = "Die Gnomenboxen der Illusionenrennbahn",
	hint = [=[Sprecht mit dem Gnom, der sich sorgt, dass der Raketenwagen in einem Stück bleibt.]=],
	allegiance = "Gnomisches Rennteam",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Wizzle Brassbolts ist der Bruder, der sich sorgt. Er glaubt, dass Fizzles neuer Treibstoff stark genug ist, um sich durch den Wagen selbst zu fressen, also baut er Tanks aus den Panzern der großen Schildkröten der Ebene. Er fürchtet, dass der Wagen von seiner eigenen Geschwindigkeit zerrissen wird, also bestreicht er dessen bewegliche Teile mit einer Paste, die aus den Flossen von {link:murlocs}Murlocs{/link} gemahlen wird. Seine Piloten verunglücken trotzdem immer wieder, und er hat nach {link:ironforge}Ironforge{/link} um Helme geschickt.]=],
		},
	},
	mentions = {
		{ text = "Gehärtete Panzer" },
		{ text = "Verkrustete Schwanzflossen" },
		{ text = "Die Brüder Brassbolts" },
		{ text = "Die Brüder Brassbolts" },
		{ text = "Gahz'rilla" },
	},
	bonds = {
		{ id = "fizzle-brassbolts", name = "Fizzle Brassbolts", note = "sein Bruder" },
	},
})

Translate("deDE", "kravel-koalbeard", {
	title = "Kravel Koalbeard",
	subtitle = "Händler der Illusionenrennbahn",
	found = "Neben den Gnomenboxen der Illusionenrennbahn",
	hint = [=[Sprecht mit dem Händler, der auf der Rennbahn Wrackteile kauft und Gefälligkeiten verkauft.]=],
	allegiance = "Sein eigener Geldbeutel",
	aliases = { "Kravel" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kravel Koalbeard macht es sich zum Geschäft, den Leuten zu besorgen, was sie brauchen, und unterwegs seinen Anteil zu nehmen. Er kauft die Wracks verunglückter Rennwagen und verkauft sie an das Team zurück, das zahlt. Er führt die Bestellungen der {link:gnomes}Gnome{/link} aus, und von jeder behält er ein wenig für sich. Er glaubt, dass im Unglück anderer immer Gewinn steckt, und er sagt das frei heraus.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Kravel ist die Schattenseite der {link:mirage-raceway}Illusionenrennbahn{/link}. Durch ihn wird die Rivalität von Goblins und Gnomen zu einem Handel mit Geheimnissen, Bestechungen und betäubtem Bier, und seine Reichweite erstreckt sich von {link:ratchet}Ratchet{/link} bis {link:booty-bay}Booty Bay{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er kauft den Schrott verunglückter Rennwagen von der Ebene.
• Er nahm ein kleines Stück aus der Teilebestellung der {link:gnomes}Gnome{/link}, bevor er sie auslieferte.
• Er erfuhr ein Geheimnis des Goblinpiloten Nazz Steamboil und wollte sein Schweigen verkaufen.
• Er schickte eine Kiste besonderer Munition an seinen alten Kunden {link:hemet-nesingwary}Hemet Nesingwary{/link} im {link:stranglethorn-vale}Schlingendorntal{/link}.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Über Kravels Herkunft ist wenig geschrieben, ebenso darüber, wer seine Zeche zahlt.]=],
		},
	},
	chapters = {
		{
			title = "Das Geheimnis des Piloten",
			hint = "Erfahrt die Wahrheit über den Goblinpiloten Nazz Steamboil.",
			text = [=[Kravel hatte gehört, dass der Goblinpilot Nazz Steamboil nicht immer diesen Namen getragen hatte. Er schickte zu {link:krazek}Krazek{/link}, dem Gerüchtehändler von {link:booty-bay}Booty Bay{/link}, der mit Gefälligkeiten und einer seltenen Flasche Elfenwein bezahlte, um den Grund zu erfahren. Krazek hielt das Geheimnis für zu gefährlich, um es selbst zu nutzen. Kravel nicht. Er rechnete damit, dass Nazz ein kleines Vermögen zahlen würde, um es verborgen zu halten.]=],
		},
		{
